//! Area referrerPolicy uses known-value reflection while Attr remains exact.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><area id=area referrerpolicy=NO-REFERRER><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://area-referrer-policy.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn area_referrer_policy_canonical_descriptor_and_known_initial_value(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),a=Object.getOwnPropertyDescriptor(HTMLAreaElement.prototype,'referrerPolicy');if(!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get referrerPolicy'||a.set.name!=='set referrerPolicy'||Object.hasOwn(x,'referrerPolicy')||x.referrerPolicy!=='no-referrer'||x.getAttribute('referrerpolicy')!=='NO-REFERRER')throw 'canonical known-value accessor';"#);}
#[test]
fn area_referrer_policy_native_keywords_raw_aliases_and_invalid_default(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),a=x.getAttributeNode('referrerpolicy');for(var keyword of ['','no-referrer','no-referrer-when-downgrade','same-origin','origin','strict-origin','origin-when-cross-origin','strict-origin-when-cross-origin','unsafe-url']){var raw=keyword.toUpperCase();x.referrerPolicy=raw;if(x.referrerPolicy!==keyword||a.value!==raw||x.getAttributeNode('referrerpolicy')!==a)throw 'known canonical value preserves raw spelling';}for(var value of ['unknown',' origin','origin ','origin,no-referrer','A\ud800Z']){x.referrerPolicy=value;if(x.referrerPolicy!==''||a.value!==value)throw 'invalid raw setter default';}a.nodeValue='ORIGIN';if(x.referrerPolicy!=='origin'||a.value!=='ORIGIN')throw 'attached raw alias';a.value='R\udfffZ';if(x.referrerPolicy!==''||a.value!=='R\udfffZ')throw 'raw alias is not rewritten';x.removeAttribute('referrerpolicy');if(x.referrerPolicy!==''||a.ownerElement!==null||a.value!=='R\udfffZ')throw 'missing value default';"#);}
#[test]
fn area_referrer_policy_inert_once_conversion_namespace_and_clone(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','t:area');if(x.referrerPolicy!=='')throw 'inert missing value';var calls=0;x.referrerPolicy={toString:function(){calls++;x.setAttribute('referrerpolicy','author');return 'SAME-ORIGIN';}};if(calls!==1||x.referrerPolicy!=='same-origin'||x.getAttribute('referrerpolicy')!=='SAME-ORIGIN')throw 'once conversion before known lookup';x.setAttributeNS('urn:foreign','referrerpolicy','unsafe-url');x.setAttributeNS(null,'REFERRERPOLICY','origin');var clone=x.cloneNode(false);if(x.referrerPolicy!=='same-origin'||clone.referrerPolicy!=='same-origin'||clone.getAttribute('referrerpolicy')!=='SAME-ORIGIN')throw 'exact namespace and clone';clone.referrerPolicy='ORIGIN';if(x.referrerPolicy!=='same-origin'||clone.referrerPolicy!=='origin')throw 'independent clone';"#);}
#[test]
fn area_referrer_policy_saved_child_origin_precedes_conversion_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var C=frame.contentWindow.HTMLAreaElement,a=Object.getOwnPropertyDescriptor(C.prototype,'referrerPolicy'),calls=0;if(C===HTMLAreaElement||a.get.call(x)!=='no-referrer')throw 'captured area accessor';"#);p.set_location(&crate::navigation::address("https://other-time.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'bad';}});"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://area-referrer-policy.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin precedes conversion';a.set.call(x,'ORIGIN');if(a.get.call(x)!=='origin')throw 'area origin recovery';");
}

// Shared reflection transactions must refuse before observable changes.
#[test]
fn area_referrer_policy_writer_refusal_preserves_native_and_inert_records_and_recovers(){
 for inert in [false,true]{for source in [r"x.referrerPolicy='Long canonical \ud800 DateTime replacement';",r"x.setAttribute('referrerpolicy','Long canonical \ud800 DateTime replacement');",r"attr.value='Long canonical \ud800 DateTime replacement';",r"attr.nodeValue='Long canonical \ud800 DateTime replacement';",r"attr.textContent='Long canonical \ud800 DateTime replacement';"]{for mode in 0..5{
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','area');x.setAttribute('referrerpolicy','NO-REFERRER');"}else{"var x=document.getElementById('area');"});run(&mut d,&mut f,&mut p,"var attr=x.getAttributeNode('referrerpolicy'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("alt writer {inert}/{source}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(attr.value!=='NO-REFERRER'||x.referrerPolicy!=='no-referrer'||watch.takeRecords().length)throw 'atomic alt writer refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,r"var records=watch.takeRecords();if(x.referrerPolicy!==''||attr.value!=='Long canonical \ud800 DateTime replacement'||records.length!==1||records[0].oldValue!=='NO-REFERRER'||records[0].attributeName!=='referrerpolicy'||x.getAttributeNode('referrerpolicy')!==attr)throw 'fresh alt writer recovery';");
 }}}
}
#[test]
fn area_referrer_policy_reads_enforce_work_copy_string_and_deadline_without_retained_growth(){
 for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();let object=if inert{run(&mut d,&mut f,&mut p,r"var time=new Document().createElementNS('http://www.w3.org/1999/xhtml','area');time.referrerPolicy='A\ud800Z';");let Value::Host(object)=p.runtime.execute("time;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("inert time handle")};object}else{run(&mut d,&mut f,&mut p,r"document.getElementById('area').referrerPolicy='A\ud800Z';");node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("area")).unwrap())};let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=1,3=>p.state.execution_deadline=Some(Instant::now()),_=>p.state.retained_limit=p.state.retained};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.area_referrer_policy_get(object);if mode==4{assert!(result.is_ok());}else{let e=result.unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("time")||e.contains("bound"),"{e}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.execution_deadline=None;p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.begin_job();assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.area_referrer_policy_get(object).is_ok());}}
}


#[test]
fn area_referrer_policy_native_copy_import_and_neighbor_attribute_guards_remain_atomic(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),source=new Document().createElementNS('http://www.w3.org/1999/xhtml','area');source.referrerPolicy='ORIGIN';var neighbor=document.getElementById('neighbor');");
 for code in ["x.cloneNode(false);","document.importNode(source,false);",r"neighbor.setAttribute('referrerpolicy','A\ud800Z');"]{let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("not implemented")||e.contains("Import supports ordinary HTML containers and inert data nodes.")||e.contains("Unpaired attribute"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);p.begin_job();run(&mut d,&mut f,&mut p,"if(source.referrerPolicy!=='origin'||x.referrerPolicy!=='no-referrer'||neighbor.value!=='seed'||neighbor.hasAttribute('referrerpolicy'))throw 'preserved native and neighbor guards';");}
}


#[test]
fn area_referrer_policy_conversion_reentry_abrupt_and_symbol_order(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),old=x.getAttributeNode('referrerpolicy'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});var calls=0;x.referrerPolicy={toString:function(){calls++;x.removeAttribute('referrerpolicy');x.setAttribute('referrerpolicy','origin');return 'SAME-ORIGIN';}};var attr=x.getAttributeNode('referrerpolicy'),records=watch.takeRecords();if(calls!==1||attr===old||old.ownerElement!==null||old.value!=='NO-REFERRER'||attr.value!=='SAME-ORIGIN'||x.referrerPolicy!=='same-origin'||records.length!==3||records[2].oldValue!=='origin')throw 'current raw Attr after conversion';var marker={},caught;try{x.referrerPolicy={toString:function(){x.setAttribute('referrerpolicy','unsafe-url');throw marker;}};}catch(e){caught=e;}records=watch.takeRecords();if(caught!==marker||x.referrerPolicy!=='unsafe-url'||records.length!==1||records[0].oldValue!=='SAME-ORIGIN')throw 'abrupt conversion preserves author effect';caught=false;try{x.referrerPolicy=Symbol('policy');}catch(e){caught=e instanceof TypeError;}if(!caught||watch.takeRecords().length||x.referrerPolicy!=='unsafe-url')throw 'symbol before mutation';for(var value of [null,undefined,0,false]){x.referrerPolicy=value;if(x.referrerPolicy!==''||attr.value!==String(value))throw 'ordinary DOMString conversion and invalid default';}"#);
}
#[test]
fn area_referrer_policy_brands_author_override_and_saved_constructor(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),C=HTMLAreaElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'referrerPolicy'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElementNS('urn:foreign','area'),new Document().createElementNS('http://www.w3.org/1999/xhtml','AREA')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'getter genuine brand';caught=false;try{a.set.call(bad,{toString:function(){calls++;return 'origin';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'brand before conversion';}Object.defineProperty(x,'referrerPolicy',{value:'author',writable:true,configurable:true});if(a.get.call(x)!=='no-referrer'||x.referrerPolicy!=='author')throw 'canonical read authority';a.set.call(x,'ORIGIN');if(x.referrerPolicy!=='author'||x.getAttribute('referrerpolicy')!=='ORIGIN')throw 'canonical raw setter';delete x.referrerPolicy;if(x.referrerPolicy!=='origin'||Object.hasOwn(x,'referrerPolicy'))throw 'restored inherited policy';delete window.HTMLAreaElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved native interface';"#);
}
#[test]
fn area_referrer_policy_native_inert_raw_aliases_and_namespace(){
 for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','t:area');x.setAttribute('referrerpolicy','NO-REFERRER');"}else{"var x=document.getElementById('area');"});run(&mut d,&mut f,&mut p,r#"var attr=x.getAttributeNode('referrerpolicy'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});for(var writer of ['value','nodeValue','textContent']){attr[writer]='R\ud800'+writer;if(x.referrerPolicy!==''||attr.value!=='R\ud800'+writer||x.getAttributeNode('referrerpolicy')!==attr)throw 'exact raw alias invalid default';}watch.takeRecords();x.setAttributeNS('urn:foreign','referrerpolicy','origin');x.setAttributeNS(null,'REFERRERPOLICY','unsafe-url');watch.takeRecords();if(x.referrerPolicy!==''||attr.value!=='R\ud800textContent')throw 'exact null namespace';x.setAttributeNS(null,'referrerpolicy','STRICT-ORIGIN');var records=watch.takeRecords();if(x.referrerPolicy!=='strict-origin'||attr.value!=='STRICT-ORIGIN'||records.length!==1||records[0].attributeName!=='referrerpolicy'||records[0].oldValue!=='R\ud800textContent'||watch.takeRecords().length)throw 'known getter without source mutation';"#);}
}
